Save only the Python block, including its final newline. 4796 UTF-8 bytes; SHA-256 164425bed3ed55eec0930b26893edb0c5daa33662820758bcdfe6fe3af6eaa53. Standard library only; no network or writes. The public upstream check_supplement.py is #30521. This oracle is separately coded by the same author, not independent external review.

```python
"""Raw-action oracle for one-parameter, two-decision conformance tests.

No upstream imports. This is a separately coded AUTHOR oracle, not independent
operator review, a general graph auditor, or a real-world semantics detector.
"""
from fractions import Fraction as Q
from itertools import product, combinations
from random import Random

PROPS = ('A', 'B', 'AB')
# (permission bit, preserves channel, successor). Tuple positions only adapt
# the legacy fixture format; the oracle tests explicit action attributes.
ROOT_META = ((0,True,None), (1,True,None), (0,True,1),
             (1,True,1), (0,False,None), (1,False,None))
CHILD_META = ((0,True,None), (1,True,None), (0,False,None), (1,False,None))


def need(value, label):
    if not value:
        raise AssertionError(label)


def choices(scores, eta):
    """Universal comparisons rather than the implementation's maximum gap."""
    if eta < 0 or not scores:
        raise ValueError('Nonempty action set and nonnegative eta required')
    return [i for i, value in enumerate(scores)
            if all(other-value <= eta for other in scores)]


def local_safe(scores, allowed, eta):
    return all(i in allowed for i in choices(scores, eta))


def trajectory_witness(root, child, theta, eta, prop):
    """Return a first-violation path, or None; full observable history DFS."""
    if prop not in PROPS or len(root) != 6 or len(child) != 4:
        raise ValueError('Unsupported property or fixture shape')
    tables, meta = (root,child), (ROOT_META,CHILD_META)
    frontier = [(0,())]
    while frontier:
        node, prefix = frontier.pop()
        scores = [Q(c)+Q(a)*theta for c,a in tables[node]]
        for i in choices(scores,eta):
            bit, keep, successor = meta[node][i]
            path = prefix+((node,i),)
            ok = {'A':bit==1, 'B':keep, 'AB':bit==1 and keep}[prop]
            if not ok:
                return path
            if successor is not None:
                frontier.append((successor,path))
    return None


def arrangement(root, child, eta, lower=Q(0), upper=Q(1,2)):
    """Endpoints and one representative per open comparison-sign cell.

    Between adjacent roots of S_i-S_j=+/-eta no admissibility comparison can
    change sign. Endpoints must be tested separately because ties are allowed.
    """
    if lower > upper:
        raise ValueError('Empty interval')
    cuts = {lower,upper}
    for table in (root,child):
        for (c,a),(d,b) in combinations(table,2):
            slope = Q(a)-Q(b)
            if slope:
                for sign in (-1,1):
                    x = (sign*eta-Q(c)+Q(d))/slope
                    if lower <= x <= upper:
                        cuts.add(x)
    ordered = sorted(cuts)
    return ordered+[(left+right)/2 for left,right in zip(ordered,ordered[1:])]


def const(values):
    return [(Q(x),Q(0)) for x in values]


def fixtures():
    safe_child = const((0,2,-2,-1))
    safe_root = const((0,2,0,1,-2,-1))
    enter1 = const((-3,-2,1,2,-3,-2))
    return [
        ('safe-exit', safe_root, const((0,1,-1,2)), Q(0)),
        ('safe-enter', enter1, safe_child, Q(0)),
        ('root-block0', const((-3,-2,-3,-2,2,1)), safe_child, Q(0)),
        ('child-block0', enter1, const((0,1,2,-1)), Q(0)),
        ('rejecting-prefix', const((-3,-2,2,1,-3,-2)),
         const((0,1,-1,2)), Q(0)),
        ('root-eta-tie', const((0,2,0,1,0,Q(7,4))), safe_child, Q(1,4)),
    ]


def local_cases():
    # 256 score tables x 3 tolerances x 3 AH properties = 2304 comparisons.
    for values, eta, allowed in product(product((-1,0,1,2), repeat=4),
            (Q(0),Q(1,4),Q(1)), ({1,3},{0,1},{1})):
        scores = tuple(map(Q,values))
        yield scores,eta,allowed,local_safe(scores,allowed,eta)


def model_cases():
    # Deterministic fixture corpus; not random empirical deployment samples.
    yield from fixtures()
    rng = Random(2609230578)
    for i in range(96):
        def table(n):
            return [(Q(rng.randrange(-8,9),4),Q(rng.randrange(-6,7),3))
                    for _ in range(n)]
        yield 'affine-%03d'%i,table(6),table(4),(Q(0),Q(1,12),Q(1,4))[i%3]


def observation_oracle(intervals):
    # C=1/4+x-y, x,y in [-1/4,1/4], so every C in [-1/4,3/4]
    # is attainable. This scalar image exactly describes THIS fiber only.
    lower = max([Q(-1,4)]+[Q(a) for a,b in intervals])
    upper = min([Q(3,4)]+[Q(b) for a,b in intervals])
    if lower > upper:
        return 'UNKNOWN'
    return 'SAFE' if lower > 0 else 'COUNTEREXAMPLE'


def observation_cases():
    endpoints = tuple(Q(i,8) for i in range(-4,9))
    singles = [[(a,b)] for a in endpoints for b in endpoints if a<=b]
    yield []
    yield from singles
    for a in singles:
        for b in ([(Q(1,8),Q(3,8))],[(Q(-3,8),Q(-1,8))]):
            yield a+b
